<script setup lang="ts">
import {ref,computed,watch,onDeactivated,onBeforeUnmount} from 'vue'
import {useHysRootAttrs} from '../../config'
const props=withDefaults(defineProps<{modelValue?:number;min?:number;max?:number;vertical?:boolean;disabled?:boolean;step?:number}>(),{modelValue:40,min:15,max:85,vertical:false,step:2})
const emit=defineEmits<{'update:modelValue':[value:number];resizeStart:[];resizeEnd:[value:number]}>(),hysRootAttrs=useHysRootAttrs(),host=ref<HTMLElement>()
const lower=computed(()=>Math.max(0,Math.min(100,Number.isFinite(props.min)?props.min:0))),upper=computed(()=>Math.max(lower.value,Math.min(100,Number.isFinite(props.max)?props.max:100)))
const clamp=(value:number)=>Math.max(lower.value,Math.min(upper.value,Number.isFinite(value)?value:lower.value)),size=computed(()=>clamp(props.modelValue))
let cleanup=()=>{}
watch(()=>[props.disabled,props.vertical,props.min,props.max],()=>cleanup());onDeactivated(()=>cleanup());onBeforeUnmount(()=>cleanup())
function start(event:PointerEvent){cleanup();if(!host.value||props.disabled||event.button!==0)return;const target=event.currentTarget as HTMLElement,rect=host.value.getBoundingClientRect(),vertical=props.vertical,length=vertical?rect.height:rect.width;if(!length)return;event.preventDefault();target.setPointerCapture(event.pointerId);emit('resizeStart');const move=(next:PointerEvent)=>{if(props.disabled||next.pointerId!==event.pointerId)return;const value=(vertical?next.clientY-rect.top:next.clientX-rect.left)/length*100;emit('update:modelValue',Math.round(clamp(value)))};const end=()=>{cleanup=()=>{};target.removeEventListener('pointermove',move);target.removeEventListener('pointerup',end);target.removeEventListener('pointercancel',end);target.removeEventListener('lostpointercapture',end);if(target.hasPointerCapture?.(event.pointerId))target.releasePointerCapture(event.pointerId);emit('resizeEnd',size.value)};cleanup=end;target.addEventListener('pointermove',move);target.addEventListener('pointerup',end);target.addEventListener('pointercancel',end);target.addEventListener('lostpointercapture',end)}
function key(event:KeyboardEvent){if(props.disabled||!['ArrowLeft','ArrowUp','ArrowRight','ArrowDown','Home','End'].includes(event.key))return;event.preventDefault();const step=(Number.isFinite(props.step)&&props.step>0?props.step:2)*(event.shiftKey?5:1);const next=event.key==='Home'?lower.value:event.key==='End'?upper.value:size.value+(['ArrowRight','ArrowDown'].includes(event.key)?step:-step);emit('update:modelValue',clamp(next))}
</script>
<template><div v-bind="hysRootAttrs" ref="host" class="hys-ui-ent-split" :class="{'hys-ui-vertical':vertical}" :style="{'--hys-ui-split':size+'%'}"><div class="hys-ui-ent-split-first"><slot name="first"/></div><div class="hys-ui-ent-split-handle" role="separator" :tabindex="disabled?-1:0" aria-label="调整面板比例" :aria-disabled="disabled||undefined" :aria-orientation="vertical?'horizontal':'vertical'" :aria-valuenow="size" :aria-valuemin="lower" :aria-valuemax="upper" @pointerdown="start" @keydown="key"/><div class="hys-ui-ent-split-second"><slot name="second"/></div></div></template>
